long sys_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops, const struct timespec __user *timeout) {
    struct oabi_sembuf *sops;
    long ret = -EINVAL;
    int i;

    if (nsops == 0)
        return -EINVAL;

    sops = kmalloc(sizeof(struct oabi_sembuf) * nsops, GFP_KERNEL);
    if (!sops)
        return -ENOMEM;

    if (copy_from_user(sops, tsops, nsops * sizeof(struct oabi_sembuf))) {
        kfree(sops);
        return -EFAULT;
    }

    for (i = 0; i < nsops; i++) {
        struct oabi_sembuf *sop = &sops[i];
        if (sop->sem_num >= MAX_SEMNUM || (sop->sem_op == 0 && (sop->sem_flg & SEM_UNDO))) {
            kfree(sops);
            return -EINVAL;
        }
    }

    if (timeout) {
        struct timespec to;
        if (copy_from_user(&to, timeout, sizeof(to))) {
            kfree(sops);
            return -EFAULT;
        }
        ret = do_semtimedop(semid, sops, nsops, &to);
    } else {
        ret = do_semtimedop(semid, sops, nsops, NULL);
    }

    kfree(sops);
    return ret;
}

long sys_semtimedop(int semid, struct oabi_sembuf __user *tsops,
                    unsigned nsops, const struct timespec __user *timeout)
{
    struct oabi_sembuf *sops;
    int i;
    long ret = -EINVAL;

    if (nsops == 0)
        return -EINVAL;

    sops = (struct oabi_sembuf *)__get_free_pages(GFP_KERNEL, 0);
    if (!sops)
        return -ENOMEM;

    if (copy_from_user(sops, tsops, nsops * sizeof(struct oabi_sembuf))) {
        ret = -EFAULT;
        goto out;
    }

    for (i = 0; i < nsops; i++) {
        sops[i].sem_op = (short) sops[i].sem_op;
        sops[i].sem_flg = (short) sops[i].sem_flg;
    }

    if (timeout) {
        struct timespec to;
        if (copy_from_user(&to, timeout, sizeof(to))) {
            ret = -EFAULT;
            goto out;
        }
        ret = do_semtimedop(semid, sops, nsops, &to);
    } else {
        ret = do_semtimedop(semid, sops, nsops, NULL);
    }

out:
    free_pages((unsigned long)sops, 0);
    return ret;
}

long do_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops, const struct timespec __user *timeout) {
    long ret = -EINVAL;
    struct sembuf *sops = NULL;

    if (!nsops)
        return -EINVAL;

    sops = kmalloc_array(nsops, sizeof(struct sembuf), GFP_KERNEL);
    if (!sops)
        return -ENOMEM;

    if (copy_from_user(sops, tsops, nsops * sizeof(struct sembuf))) {
        kfree(sops);
        return -EFAULT;
    }

    struct timespec to;
    if (timeout && copy_from_user(&to, timeout, sizeof(struct timespec))) {
        kfree(sops);
        return -EFAULT;
    }

    ret = sys_semtimedop(semid, sops, nsops, timeout ? &to : NULL);

    kfree(sops);
    return ret;
}

long sys_semtimedop(int semid, struct oabi_sembuf __user *tsops, unsigned nsops, const struct timespec __user *timeout) {
    struct oabi_sembuf *sops;
    long ret = -EINVAL;
    int i;

    if (nsops == 0)
        return -EINVAL;

    sops = kmalloc_array(nsops, sizeof(*sops), GFP_KERNEL);
    if (!sops)
        return -ENOMEM;

    if (copy_from_user(sops, tsops, nsops * sizeof(*sops)))
        goto out_free;

    if (timeout) {
        struct timespec to;
        if (copy_from_user(&to, timeout, sizeof(to)))
            goto out_free;
        ret = do_semtimedop(semid, sops, nsops, &to);
    } else {
        ret = do_semtimedop(semid, sops, nsops, NULL);
    }

out_free:
    kfree(sops);
    return ret;
}

